.ds-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  min-height: 44px;
  padding: 12px 20px;
  background: var(--blue,#17274c);
  border: 1px solid transparent;
  border-radius: 9px;
  color: #fff;
  font-size: 13px;
  font-weight: 700;
  line-height: 1.3;
  white-space: nowrap;
  transition:
    background 0.18s,
    transform 0.18s;
}

.ds-button:hover {
  background: var(--blue-dark,#111e3b);
  transform: translateY(-1px);
}

@media (prefers-reduced-motion: reduce) { .ds-button:hover { transform: none; } }
.ds-button:focus-visible{outline:3px solid #657496;outline-offset:3px}

