.ds-nav {
  display: flex;
  flex-direction: column;
  gap: 7px;
}

.ds-nav a {
  display: flex;
  align-items: center;
  gap: 13px;
  min-height: 46px;
  padding: 0 13px;
  color: #656971;
  font-size: 12px;
  font-weight: 600;
  border-radius: 8px;
}

.ds-nav a:hover {
  background: #f4f5f7;
  color: var(--blue,#17274c);
}

.ds-nav a.active {
  background: var(--ice,#e8ebf2);
  color: var(--blue,#17274c);
  font-weight: 800;
}

.ds-nav a:focus-visible{outline:3px solid #657496;outline-offset:3px}

.ds-card {
  border: 1px solid var(--line,#e8e9ec);
  border-radius: 13px;
  overflow: hidden;
  background: #fff;
  transition: border-color 0.2s;
}

.ds-card:hover {
  border-color: #b5bccb;
}

.ds-card-body {
  padding: 17px 17px 15px;
}




.ds-card h3{font:600 18px "Bricolage Grotesque Variable",sans-serif}.ds-card p{font:12px "Manrope Variable",sans-serif;color:#696c72}

.ds-language {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  color: var(--blue,#17274c);
  position: relative;
  flex-shrink: 0;
}

.ds-language select {
  min-height: 38px;
  border: 1px solid #dfe1e5;
  background: #fff;
  padding: 7px 23px 7px 10px;
  border-radius: 7px;
  font-size: 11px;
  color: var(--blue,#17274c);
  cursor: pointer;
  font-weight: 650;
  max-width: 112px;
}

  .ds-language select {
    font-size: 10px;
    padding: 7px 17px 7px 8px;
    max-width: 100px;
  }

.ds-language select {
  min-height: 44px;
  font-size: 12px;
}

  .ds-language select {
    font-size: 12px;
  }.ds-language select:focus-visible{outline:3px solid #657496;outline-offset:3px}

.ds-demo p {
  flex: 1 1 250px;
}

.ds-demo a {
  display: inline-flex;
